def source_inventory(repo, reviewed, *, source_policy):
    source_policy = _bounded_current.admit_policy(source_policy)
    source_policy.require_manifest_document(reviewed)
    paths = [repo / name for name in ('Cargo.toml', 'Cargo.lock', 'build.rs')]
    def scan_root(name):
        directory = repo
        for part in Path(name).parts:
            directory /= part
            if directory.is_symlink():
                raise ValueError('source snapshots reject symlink directories: ' + str(directory))
        return directory
    # The Rust binary also embeds compiler/stdlib text and its owned RFC through
    # include_str!, so those inputs belong to the build identity as well.
    for name in ('src', 'native', 'compiler', 'stdlib', 'rfcs', '.cargo',
                 'fixtures/owned_source', 'tests/fixtures/owned_source'):
        for path in scan_root(name).rglob('*'):
            if path.is_symlink():
                raise ValueError('source snapshots reject symlinks: ' + str(path))
            if path.is_file():
                paths.append(path)
    paths.extend(path for path in scan_root('scripts').glob('*owned*.py'))
    if reviewed is not None:
        # Production calls admit the pinned complete current manifest first.
        # Retain all compile-time fixtures, including those outside the legacy
        # owned-source fixture roots; the unchanged replay inventory stays separate.
        paths.extend(scan_root(row['path']) for row in reviewed['files'])
        current_source.reviewed_input_identities(repo, reviewed)
        paths.extend(repo / name for name in (
            source_policy.manifest_path,
            'scripts/verify_bounded_enum_native.py'))
    paths.extend(repo / name for name in source_policy.controller_members)
    paths = sorted(set(paths))
    if any(path.is_symlink() for path in paths):
        raise ValueError('source snapshots require regular input files')
    return {str(path.relative_to(repo)): digest(path) for path in paths}

